import { useState, type CSSProperties } from "react";

const panelStyle: CSSProperties = {
  backgroundColor: "#eef2ff",
  color: "#172554",
  padding: 16,
};

function useModel() {
  const [value, setValue] = useState(0);
  const increment = () => setValue((current) => current + 1);
  const reset = () => setValue(0);
  return { value, increment, reset };
}

export function Counter() {
  const { value, increment, reset } = useModel();
  return <section style={panelStyle} aria-label="Counter"><output>{value}</output><button onClick={increment}>증가</button><button onClick={reset}>초기화</button></section>;
}

