import { useState, type CSSProperties } from "react";

const panelStyle: CSSProperties = {
  backgroundColor: "#eef2ff",
  color: "#172554",
  padding: 16,
};

function useModel() {
  const [value, setValue] = useState([false, false]);
  const toggleRead = () => setValue((current) => current.map((done, index) => index === 0 ? !done : done));
  const toggleReview = () => setValue((current) => current.map((done, index) => index === 1 ? !done : done));
  return { value, toggleRead, toggleReview };
}

export function Checklist() {
  const { value, toggleRead, toggleReview } = useModel();
  return <section style={panelStyle} aria-label="Checklist"><button aria-pressed={value[0]} onClick={toggleRead}>읽기 {value[0] ? "완료" : "미완료"}</button><button aria-pressed={value[1]} onClick={toggleReview}>검토 {value[1] ? "완료" : "미완료"}</button></section>;
}

